 * [👤semio🏪assets💻index🔖exports🪨metabolismkitportsbyguid](repo://p/u/semio/b/a/assets/f/index.ts/s/Exports/d/i/MetabolismKitPortsByGuid)
 **/
export const MetabolismKitPortsByGuid = portLookup.byGuid;
/**
